<script setup>
import { onMounted, ref, watch } from 'vue'
import { ExternalLink, MoreHorizontal, Plus, Search, SlidersHorizontal } from 'lucide-vue-next'
import { RouterLink, useRouter } from 'vue-router'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AdminState from '../../components/admin/AdminState.vue'
import ConfirmModal from '../../components/admin/ConfirmModal.vue'
import { deleteAdminCourse, getAdminCourses, getCategories, updateCoursePublication } from '../../services/adminApi'

const router = useRouter()
const courses = ref([]); const categories = ref([]); const meta = ref(null); const loading = ref(true); const error = ref(''); const deleting = ref(false); const selected = ref(null)
const filters = ref({ search: '', status: '', featured: '', category_id: '', modality: '', page: 1, per_page: 15 })
let searchTimer
function formatDate(value) { return value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—' }
function load(page = filters.value.page) { filters.value.page = page; loading.value = true; error.value = ''; return getAdminCourses(filters.value).then((payload) => { courses.value = payload.data; meta.value = payload.meta }).catch((requestError) => { error.value = requestError.message }).finally(() => { loading.value = false }) }
onMounted(async () => { try { const categoryPayload = await getCategories(); categories.value = categoryPayload.data; await load() } catch (requestError) { error.value = requestError.message; loading.value = false } })
watch(() => [filters.value.status, filters.value.featured, filters.value.category_id, filters.value.modality], () => load(1))
function searchCourses() { clearTimeout(searchTimer); searchTimer = setTimeout(() => load(1), 300) }
async function togglePublication(course) { try { await updateCoursePublication(course.id, !course.is_published); await load() } catch (requestError) { error.value = requestError.message } }
async function destroyCourse() { if (!selected.value) return; deleting.value = true; try { await deleteAdminCourse(selected.value.id); selected.value = null; await load() } catch (requestError) { error.value = requestError.message } finally { deleting.value = false } }
function viewPublic(course) { window.open(`/cursos/${course.slug}`, '_blank', 'noopener') }
</script>

<template><AdminPageHeader title="Cursos" description="Cadastre e mantenha as informações do catálogo público atualizadas."><template #actions><RouterLink class="admin-button primary" :to="{ name: 'admin-course-new' }"><Plus :size="18" />Novo curso</RouterLink></template></AdminPageHeader><div class="admin-filter-card"><div class="admin-search-input"><Search :size="18" /><input v-model="filters.search" type="search" placeholder="Buscar por nome ou slug" @input="searchCourses" /></div><div class="admin-filter-row"><label><span>Status</span><select v-model="filters.status"><option value="">Todos</option><option value="published">Publicados</option><option value="draft">Rascunhos</option></select></label><label><span>Destaque</span><select v-model="filters.featured"><option value="">Todos</option><option value="1">Em destaque</option><option value="0">Sem destaque</option></select></label><label><span>Categoria</span><select v-model="filters.category_id"><option value="">Todas</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label><span>Modalidade</span><select v-model="filters.modality"><option value="">Todas</option><option>Formação</option><option>Atualização</option></select></label><span class="filter-label"><SlidersHorizontal :size="16" />Filtros na API</span></div></div><p v-if="error" class="form-alert error" role="alert">{{ error }}</p><AdminState v-if="loading" message="Carregando cursos…" /><AdminState v-else-if="!courses.length" type="empty" message="Nenhum curso encontrado com estes filtros."><RouterLink class="admin-button primary" :to="{ name: 'admin-course-new' }">Cadastrar primeiro curso</RouterLink></AdminState><section v-else class="admin-table-card"><div class="admin-table-wrap"><table><thead><tr><th>Curso</th><th>Categoria</th><th>Modalidades</th><th>Destaque</th><th>Status</th><th>Atualizado em</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><tr v-for="course in courses" :key="course.id"><td><div class="table-course"><span class="table-image"><img v-if="course.cover_image_path" :src="course.cover_image_path" alt="" /><span v-else>{{ course.short_name?.slice(0, 2) || 'EC' }}</span></span><div><RouterLink :to="{ name: 'admin-course-edit', params: { id: course.id } }">{{ course.name }}</RouterLink><small>/cursos/{{ course.slug }}</small></div></div></td><td>{{ course.category?.name || '—' }}</td><td><span v-for="modality in course.modalities" :key="modality.id" class="tag">{{ modality.name }}</span></td><td><span :class="course.is_featured ? 'status featured' : 'muted-text'">{{ course.is_featured ? 'Sim' : 'Não' }}</span></td><td><button class="status-button" :class="course.is_published ? 'published' : 'draft'" type="button" @click="togglePublication(course)">{{ course.is_published ? 'Publicado' : 'Rascunho' }}</button></td><td>{{ formatDate(course.updated_at) }}</td><td><div class="row-actions"><button type="button" title="Ver página pública" aria-label="Ver página pública" @click="viewPublic(course)"><ExternalLink :size="17" /></button><button type="button" title="Editar curso" aria-label="Editar curso" @click="router.push({ name: 'admin-course-edit', params: { id: course.id } })"><MoreHorizontal :size="19" /></button><button class="row-delete" type="button" title="Excluir curso" aria-label="Excluir curso" @click="selected = course">Excluir</button></div></td></tr></tbody></table></div><div v-if="meta" class="admin-pagination"><span>{{ meta.from }}–{{ meta.to }} de {{ meta.total }} cursos</span><div><button class="admin-button ghost" type="button" :disabled="meta.current_page <= 1" @click="load(meta.current_page - 1)">Anterior</button><button class="admin-button ghost" type="button" :disabled="meta.current_page >= meta.last_page" @click="load(meta.current_page + 1)">Próxima</button></div></div></section><ConfirmModal :open="Boolean(selected)" title="Excluir este curso?" description="O curso deixará de existir no catálogo. Esta ação não pode ser desfeita." confirm-label="Excluir curso" :busy="deleting" @cancel="selected = null" @confirm="destroyCourse" /></template>
